//! Padrões do `Intl.RelativeTimeFormat` de 37 línguas (as 38 locales do escopo, sem de-AT que é igual a de), medidos no bun.
//!
//! ARQUIVO GERADO: não edite à mão. Para regenerar, na raiz de `wip/zjsc`:
//!
//! ```text
//! bun scripts/gen-reltime-golden.js
//! ```
//!
//! O mesmo script escreve `tests/golden/reltime_bun.tsv`, que `tests/reltime_bun_golden.rs` confere.

/// Índices de estilo: `long` 0, `short` 1, `narrow` 2. Índices de unidade: `second` 0, `minute` 1, `hour` 2,
/// `day` 3, `week` 4, `month` 5, `quarter` 6, `year` 7. Índices de categoria de plural: `zero` 0, `one` 1,
/// `two` 2, `few` 3, `many` 4, `other` 5; o texto vazio quer dizer "use `other`".
pub struct Entry {
    pub lang: &'static str,
    pub style: u8,
    pub unit: u8,
    pub past: [&'static str; 6],
    pub future: [&'static str; 6],
}

/// Os textos de `numeric: "auto"`: língua, estilo, unidade, valor (-2 a 2) e texto.
pub struct AutoText {
    pub lang: &'static str,
    pub style: u8,
    pub unit: u8,
    pub value: i8,
    pub text: &'static str,
}

